//! The Identity Sled & Shuttle Bridge
//!
//! THE SLED: a `#[repr(C)]` struct written into `/dev/shm/plugin_schema.dat`
//! by the SchemaEngine whenever the active PluginSchema mutates.
//!
//! THE SHUTTLE: reads that mapping via zero-copy mmap, extracts the
//! Strike/Etch (hashed footprint + WireGuard identity), stamps
//! `GB_FOOTPRINT` / `GB_TRACE_ID` into the process environment, then
//! writes a stateless Xray config into `/dev/shm/xray-ghostbridge.json`
//! and spawns Xray — all without touching any Btrfs-backed path.

use memmap2::MmapOptions;
use std::collections::HashSet;
use std::env;
use std::fs::{self, File};
use std::io::Write;
use std::process::Command;
use std::sync::atomic::{AtomicU64, Ordering};
use zbus::{Connection, Proxy};

pub const SHM_SLED_PATH: &str = "/dev/shm/plugin_schema.dat";
pub const SHM_XRAY_CONFIG: &str = "/dev/shm/xray-ghostbridge.json";

// ── Subid taxonomy ────────────────────────────────────────────────────────────

/// Seven operational categories for the subid taxonomy.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SubidCategory {
    /// Authoritative source / ingress channel.
    Src,
    /// Source-to-object projection / mirror publication.
    Prj,
    /// Schema contract / vocabulary / control-mapping artifact.
    Sch,
    /// Write-path mutation / state change.
    Mut,
    /// Read-path observation / enumeration / discovery.
    Obs,
    /// Emitted signal / audit-chain event / proof.
    Evt,
    /// Consumer-facing rendering / materialized presentation surface.
    Exp,
}

impl SubidCategory {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Src => "src",
            Self::Prj => "prj",
            Self::Sch => "sch",
            Self::Mut => "mut",
            Self::Obs => "obs",
            Self::Evt => "evt",
            Self::Exp => "exp",
        }
    }

    pub fn parse(s: &str) -> Option<Self> {
        match s {
            "src" => Some(Self::Src),
            "prj" => Some(Self::Prj),
            "sch" => Some(Self::Sch),
            "mut" => Some(Self::Mut),
            "obs" => Some(Self::Obs),
            "evt" => Some(Self::Evt),
            "exp" => Some(Self::Exp),
            _ => None,
        }
    }
}

/// Parsed subid components.
///
/// Pattern: `<category>.<component-type>.<subject>.<verb>[.<facet>][@vN]`
/// Example:  `sch.network.plugin-schema.resolve@v1`
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SubidTaxonomy {
    pub category: SubidCategory,
    pub component_type: String,
    pub subject: String,
    pub verb: String,
    pub facet: Option<String>,
    pub version: u8,
}

impl SubidTaxonomy {
    /// Parse a subid string into its taxonomy components.
    pub fn parse(s: &str) -> Result<Self, String> {
        // Strip optional @vN suffix
        let (body, version) = if let Some(at) = s.rfind('@') {
            let ver_str = &s[at + 1..];
            let ver: u8 = ver_str
                .strip_prefix('v')
                .and_then(|n| n.parse().ok())
                .ok_or_else(|| format!("invalid version suffix: {ver_str}"))?;
            (&s[..at], ver)
        } else {
            (s, 0)
        };

        let mut parts = body.splitn(5, '.');
        let cat_str = parts.next().ok_or("missing category")?;
        let category =
            SubidCategory::parse(cat_str).ok_or_else(|| format!("unknown category: {cat_str}"))?;
        let component_type = parts.next().ok_or("missing component-type")?.to_string();
        let subject = parts.next().ok_or("missing subject")?.to_string();
        let verb = parts.next().ok_or("missing verb")?.to_string();
        let facet = parts.next().map(str::to_string);

        // Basic segment validation: lowercase ASCII + hyphens only
        for seg in [&component_type, &subject, &verb] {
            if seg.is_empty()
                || !seg
                    .chars()
                    .all(|c| c.is_ascii_lowercase() || c == '-' || c.is_ascii_digit())
            {
                return Err(format!(
                    "invalid segment '{seg}': must be lowercase ascii/digits/hyphens"
                ));
            }
        }

        Ok(Self {
            category,
            component_type,
            subject,
            verb,
            facet,
            version,
        })
    }

    /// Reconstruct the canonical subid string.
    pub fn canonical(&self) -> String {
        let mut s = format!(
            "{}.{}.{}.{}",
            self.category.as_str(),
            self.component_type,
            self.subject,
            self.verb,
        );
        if let Some(f) = &self.facet {
            s.push('.');
            s.push_str(f);
        }
        if self.version > 0 {
            s.push_str(&format!("@v{}", self.version));
        }
        s
    }
}

impl std::fmt::Display for SubidTaxonomy {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.canonical())
    }
}

/// THE SLED — 1:1 zero-copy shared memory layout.
///
/// Written by SchemaEngine (`write_sled`), read by the Shuttle via mmap.
/// Never touches disk; lives entirely in tmpfs (`/dev/shm`).
///
/// Matches `.kiro/specs/3tched-schema-shuttle-xray-pipeline` exactly.
/// Layout (152 bytes total):
///   wireguard_pubkey    [u8; 32]   offset 0
///   mutation_index      u64        offset 32
///   hashed_footprint    [u8; 32]   offset 40   (Blake3)
///   trace_id            [u8; 16]   offset 72   (UUID v4, network order)
///   schema_version      u32        offset 88
///   reserved            [u8; 60]   offset 92
#[repr(C)]
pub struct IdentitySled {
    /// Raw Curve25519 WireGuard peer key.
    pub wireguard_pubkey: [u8; 32],
    /// Monotonic schema mutation counter.
    pub mutation_index: u64,
    /// Blake3 hashed footprint of the canonicalized schema state.
    pub hashed_footprint: [u8; 32],
    /// UUID v4 trace ID (16 raw bytes, network order).
    pub trace_id: [u8; 16],
    /// Schema version for compatibility.
    pub schema_version: u32,
    /// Qdrant vector ID for the last reasoning episode (UUID v4, 16 raw bytes).
    /// Bound to identity: every vectorized episode is traceable to this sled.
    pub vector_id: [u8; 16],
    /// Reserved for future use (zero-initialized).
    pub reserved: [u8; 44],
}

impl IdentitySled {
    pub const SIZE: usize = std::mem::size_of::<Self>();

    /// Hex-encode the trace_id field for header injection.
    pub fn trace_id_hex(&self) -> String {
        hex::encode(self.trace_id)
    }

    /// Hex-encode the vector_id for Qdrant upsert / lookup.
    pub fn vector_id_hex(&self) -> String {
        hex::encode(self.vector_id)
    }

    /// UUID string representation of vector_id.
    pub fn vector_id_uuid(&self) -> String {
        let b = self.vector_id;
        format!(
            "{:02x}{:02x}{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
            b[0],b[1],b[2],b[3],b[4],b[5],b[6],b[7],b[8],b[9],b[10],b[11],b[12],b[13],b[14],b[15]
        )
    }

    /// Absolute Base validity check per the spec:
    /// a sled is valid only if its footprint and trace_id are non-zero.
    pub fn is_sled_valid(&self) -> bool {
        self.hashed_footprint != [0u8; 32] && self.trace_id != [0u8; 16]
    }
}

// ── Zero-Btrfs disk-I/O guard ───────────────────────────────────────────────

/// Linux tmpfs magic number (`TMPFS_MAGIC`).
const TMPFS_MAGIC: libc::c_long = 0x01021994;

/// Abort if the directory backing `path` is not mounted on tmpfs.
///
/// The Shuttle must never trigger unintended Btrfs mutation loops.
/// NVMe I/O is reserved strictly for the vectorized footprint transport
/// (blockchain); all sled and Xray config writes must live in tmpfs.
fn assert_tmpfs_or_abort(path: &str) -> std::io::Result<()> {
    let parent = std::path::Path::new(path)
        .parent()
        .unwrap_or(std::path::Path::new("/"));

    let c_path = std::ffi::CString::new(parent.as_os_str().as_encoded_bytes())
        .map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidInput, e))?;

    let mut buf: libc::statfs = unsafe { std::mem::zeroed() };
    let rc = unsafe { libc::statfs(c_path.as_ptr(), &mut buf) };
    if rc != 0 {
        return Err(std::io::Error::last_os_error());
    }

    if buf.f_type as libc::c_long != TMPFS_MAGIC {
        tracing::error!(
            path = %path,
            parent = %parent.display(),
            f_type = buf.f_type,
            "ABORT: sled write would hit disk (not tmpfs). Zero-Btrfs rule violated."
        );
        return Err(std::io::Error::new(
            std::io::ErrorKind::PermissionDenied,
            format!(
                "Zero-Btrfs Overhead violation: {} is on filesystem type {}, not tmpfs",
                parent.display(),
                buf.f_type
            ),
        ));
    }

    Ok(())
}

// ── Writer side (called from SchemaEngine) ───────────────────────────────────

/// Atomically write the active sled into `/dev/shm`.
///
/// Uses a tmp-file + rename so readers never see a partial write.
/// Aborts if the target path is not on tmpfs (Zero-Btrfs Overhead rule).
pub fn write_sled(sled: &IdentitySled) -> std::io::Result<()> {
    assert_tmpfs_or_abort(SHM_SLED_PATH)?;

    let tmp = format!("{}.tmp", SHM_SLED_PATH);
    let bytes: &[u8] = unsafe {
        std::slice::from_raw_parts(sled as *const IdentitySled as *const u8, IdentitySled::SIZE)
    };
    let mut f = File::create(&tmp)?;
    f.write_all(bytes)?;
    f.sync_data()?;
    fs::rename(&tmp, SHM_SLED_PATH)?;
    Ok(())
}

// ── Reader side (the Shuttle) ────────────────────────────────────────────────

/// Read the sled from shm — zero copy, no allocation.
///
/// # Safety
/// The caller must ensure no concurrent writer is modifying the file
/// mid-read.  `write_sled` uses rename so this is safe in practice.
///
/// The sled path is overridable via the `OP_SLED_PATH` environment variable.
/// This allows tests to point at an isolated/empty memory region so the
/// "SchemaEngine unreachable" branch is deterministic regardless of host
/// SHM state. When the env var is unset, the canonical [`SHM_SLED_PATH`] is
/// used.
pub fn read_sled() -> std::io::Result<(*const IdentitySled, memmap2::Mmap)> {
    let path = std::env::var("OP_SLED_PATH").unwrap_or_else(|_| SHM_SLED_PATH.to_string());
    read_sled_at(&path)
}

/// Read the sled from an explicit path — zero copy, no allocation.
///
/// This is the testable core of [`read_sled`]. Production code should call
/// [`read_sled`] which resolves the path from the environment.
///
/// # Safety
/// The caller must ensure no concurrent writer is modifying the file
/// mid-read.  `write_sled` uses rename so this is safe in practice.
pub fn read_sled_at(path: &str) -> std::io::Result<(*const IdentitySled, memmap2::Mmap)> {
    let file = File::open(path)?;
    let mmap = unsafe { MmapOptions::new().len(IdentitySled::SIZE).map(&file)? };
    let ptr = mmap.as_ptr() as *const IdentitySled;
    Ok((ptr, mmap))
}

// ── Unix socket endpoint ──────────────────────────────────────────────────────

/// A unix socket endpoint proxied into an xray inbound + outbound pair.
///
/// Declared via `UNIX_SOCKET_ENDPOINTS=label:path:port[,…]`, e.g.:
///   `qdrant:/run/qdrant.sock:6334`
#[derive(Debug, Clone)]
pub struct SocketEntry {
    /// Xray tag suffix (e.g. `"qdrant"`) — becomes `"to-<label>"` / `"<label>-in"`.
    pub label: String,
    /// Filesystem path of the unix domain socket.
    pub path: String,
    /// Local TCP port xray should listen on and proxy into the socket.
    pub port: u16,
}

/// Parse `UNIX_SOCKET_ENDPOINTS` env var into a list of `SocketEntry`.
///
/// Format: `label:/path/to/sock:port[,…]`
/// Example: `qdrant:/run/qdrant.sock:6334`
pub fn socket_entries_from_env() -> Vec<SocketEntry> {
    let Ok(raw) = env::var("UNIX_SOCKET_ENDPOINTS") else {
        return vec![];
    };
    raw.split(',')
        .filter_map(|entry| {
            // Split into exactly 3 parts: label, path, port
            let mut parts = entry.trim().splitn(3, ':');
            let label = parts.next()?.to_string();
            let path = parts.next()?.to_string(); // already has leading '/'
            let port: u16 = parts.next()?.trim().parse().ok()?;
            Some(SocketEntry { label, path, port })
        })
        .collect()
}

// ── Xray config generator ─────────────────────────────────────────────────────

fn write_xray_config(
    footprint: &str,
    trace_id: &str,
    nextdns_profile: &str,
    uuid: &str,
    private_key: &str,
    short_id: &str,
) -> std::io::Result<()> {
    let sockets = socket_entries_from_env();
    write_xray_config_with_sockets(
        footprint,
        trace_id,
        nextdns_profile,
        uuid,
        private_key,
        short_id,
        &sockets,
    )
}

fn write_xray_config_with_sockets(
    footprint: &str,
    trace_id: &str,
    nextdns_profile: &str,
    uuid: &str,
    private_key: &str,
    short_id: &str,
    sockets: &[SocketEntry],
) -> std::io::Result<()> {
    // Build socket inbounds: one dokodemo-door per unix socket endpoint.
    let socket_inbounds: String = sockets
        .iter()
        .map(|s| {
            format!(
                r#",
    {{
      "tag": "{label}-in",
      "port": {port},
      "listen": "127.0.0.1",
      "protocol": "dokodemo-door",
      "settings": {{ "network": "tcp", "address": "127.0.0.1", "port": {port} }}
    }}"#,
                label = s.label,
                port = s.port,
            )
        })
        .collect();

    // Build socket outbounds: freedom via xray domain-socket transport.
    let socket_outbounds: String = sockets
        .iter()
        .map(|s| {
            format!(
                r#",
    {{
      "tag": "to-{label}",
      "protocol": "freedom",
      "streamSettings": {{
        "network": "ds",
        "dsSettings": {{ "path": "{path}", "abstract": false, "padding": false }}
      }}
    }}"#,
                label = s.label,
                path = s.path,
            )
        })
        .collect();

    // Build socket routing rules: inbound tag → outbound tag.
    let socket_rules: String = sockets
        .iter()
        .map(|s| {
            format!(
                r#",
      {{ "type": "field", "inboundTag": ["{label}-in"], "outboundTag": "to-{label}" }}"#,
                label = s.label,
            )
        })
        .collect();

    let config = format!(
        r#"{{
  "log": {{ "loglevel": "warning" }},
  "dns": {{
    "servers": [ "https://dns.nextdns.io/{profile}/Ghostbridge-Incus" ],
    "tag": "nextdns-in"
  }},
  "inbounds": [
    {{
      "tag": "reality-in",
      "port": 443,
      "listen": "0.0.0.0",
      "protocol": "vless",
      "settings": {{
        "clients": [{{ "id": "{uuid}", "flow": "xtls-rprx-vision" }}],
        "decryption": "none"
      }},
      "streamSettings": {{
        "network": "tcp",
        "security": "reality",
        "realitySettings": {{
          "show": false,
          "dest": "www.microsoft.com:443",
          "serverNames": ["www.microsoft.com"],
          "privateKey": "{private_key}",
          "shortIds": ["{short_id}"]
        }}
      }}
    }},
    {{
      "tag": "ovs-socks-in",
      "port": 1080,
      "listen": "10.200.0.1",
      "protocol": "socks",
      "settings": {{ "auth": "noauth", "udp": true }}
    }},
    {{
      "tag": "ovs-tproxy-in",
      "port": 12345,
      "listen": "10.200.0.1",
      "protocol": "dokodemo-door",
      "settings": {{ "network": "tcp,udp", "followRedirect": true }},
      "streamSettings": {{ "sockopt": {{ "tproxy": "tproxy" }} }}
    }}{socket_inbounds}
  ],
  "outbounds": [
    {{
      "tag": "to-grpc-bridge",
      "protocol": "freedom",
      "settings": {{ "redirect": "127.0.0.1:18789" }},
      "streamSettings": {{
        "network": "grpc",
        "sockopt": {{ "tcpNoDelay": true, "mark": 255 }},
        "grpcSettings": {{
          "serviceName": "Ghostbridge.StateSync",
          "multiMode": true,
          "metadata": {{
            "X-Ghostbridge-Footprint": "{footprint}",
            "X-Ghostbridge-Trace-ID": "{trace_id}"
          }}
        }}
      }}
    }},
    {{
      "tag": "to-cognitive-mcp",
      "protocol": "freedom",
      "sendThrough": "10.200.0.1",
      "settings": {{ "redirect": "10.200.0.2:50052" }},
      "streamSettings": {{
        "network": "grpc",
        "sockopt": {{ "tcpNoDelay": true, "mark": 255 }},
        "grpcSettings": {{
          "serviceName": "operation.cognitive.v1.CognitiveToolService",
          "multiMode": true,
          "metadata": {{
            "X-Ghostbridge-Footprint": "{footprint}",
            "X-Ghostbridge-Trace-ID": "{trace_id}"
          }}
        }}
      }}
    }},
    {{
      "tag": "direct",
      "protocol": "freedom"
    }},
    {{ "tag": "dns-out", "protocol": "dns" }}{socket_outbounds}
  ],
  "routing": {{
    "domainStrategy": "IPIfNonMatch",
    "rules": [
      {{ "type": "field", "port": 53, "outboundTag": "dns-out" }},
      {{
        "type": "field",
        "inboundTag": ["ovs-socks-in", "ovs-tproxy-in"],
        "domain": ["full:mcp.internal"],
        "outboundTag": "to-cognitive-mcp"
      }},
      {{
        "type": "field",
        "inboundTag": ["ovs-socks-in", "ovs-tproxy-in"],
        "domain": ["full:dashboard.3tched.com", "full:grpc.internal"],
        "outboundTag": "to-grpc-bridge"
      }}{socket_rules},
      {{ "type": "field", "network": "tcp,udp", "outboundTag": "direct" }}
    ]
  }}
}}"#,
        profile = nextdns_profile,
        footprint = footprint,
        trace_id = trace_id,
        uuid = uuid,
        private_key = private_key,
        short_id = short_id,
        socket_inbounds = socket_inbounds,
        socket_outbounds = socket_outbounds,
        socket_rules = socket_rules,
    );

    let tmp = format!("{}.tmp", SHM_XRAY_CONFIG);
    let mut f = File::create(&tmp)?;
    f.write_all(config.as_bytes())?;
    f.sync_data()?;
    fs::rename(&tmp, SHM_XRAY_CONFIG)?;
    Ok(())
}

// ── WireGuard-driven sled writer ─────────────────────────────────────────────

static MUTATION_INDEX: AtomicU64 = AtomicU64::new(0);

/// Decode a base64 WireGuard public key (32-byte Curve25519) into raw bytes.
fn decode_wg_pubkey(b64: &str) -> [u8; 32] {
    use base64::Engine;
    base64::engine::general_purpose::STANDARD
        .decode(b64.trim())
        .ok()
        .and_then(|v| v.try_into().ok())
        .unwrap_or([0u8; 32])
}

/// Build and atomically write the sled from live WireGuard state.
///
/// Reads `GB_TRACE_ID` from environment to propagate an existing trace;
/// if absent, mints a fresh UUID v4.  All extra metadata (subid, compliance,
/// routing) lives in environment variables — the sled itself is the spec
/// layout and nothing more.
pub fn write_sled_from_wg(peer_pubkey: &str) -> std::io::Result<()> {
    let wireguard_pubkey = decode_wg_pubkey(peer_pubkey);
    let mutation_index = MUTATION_INDEX.fetch_add(1, Ordering::Relaxed);

    // Blake3 Strike/Etch: bind pubkey to the canonical schema catalog in shm.
    // The footprint is a direct function of the single source of truth.
    let schema_catalog_hash = std::fs::read("/dev/shm/live-schema.json")
        .map(|bytes| blake3::hash(&bytes))
        .unwrap_or_else(|_| blake3::Hash::from([0u8; 32]));

    let mut hasher = blake3::Hasher::new();
    hasher.update(&wireguard_pubkey);
    hasher.update(schema_catalog_hash.as_bytes());
    hasher.update(&mutation_index.to_le_bytes());
    let hashed_footprint = hasher.finalize().into();

    // Trace propagation: reuse existing UUID if present, else mint v4
    let trace_id: [u8; 16] = if let Ok(existing) = env::var("GB_TRACE_ID") {
        hex::decode(existing.trim())
            .ok()
            .and_then(|v| v.try_into().ok())
            .unwrap_or_else(|| uuid::Uuid::new_v4().into_bytes())
    } else {
        uuid::Uuid::new_v4().into_bytes()
    };

    let sled = IdentitySled {
        wireguard_pubkey,
        mutation_index,
        hashed_footprint,
        trace_id,
        vector_id: [0u8; 16],
        schema_version: 1,
        reserved: [0u8; 44],
    };
    write_sled(&sled)
}

/// Write the sled with fully explicit fields — called from SchemaEngine on mutation.
///
/// `trace_id` is passed as hex; if empty a fresh UUID v4 is minted.
pub fn write_sled_full(
    peer_pubkey: &str,
    mutation_index: u64,
    trace_id_hex: &str,
) -> std::io::Result<()> {
    let wireguard_pubkey = decode_wg_pubkey(peer_pubkey);

    // Blake3 Strike/Etch: bind pubkey to the canonical schema catalog in shm.
    // The footprint is a direct function of the single source of truth.
    let schema_catalog_hash = std::fs::read("/dev/shm/live-schema.json")
        .map(|bytes| blake3::hash(&bytes))
        .unwrap_or_else(|_| blake3::Hash::from([0u8; 32]));

    let mut hasher = blake3::Hasher::new();
    hasher.update(&wireguard_pubkey);
    hasher.update(schema_catalog_hash.as_bytes());
    hasher.update(&mutation_index.to_le_bytes());
    let hashed_footprint = hasher.finalize().into();

    let trace_id: [u8; 16] = if trace_id_hex.is_empty() {
        uuid::Uuid::new_v4().into_bytes()
    } else {
        hex::decode(trace_id_hex.trim())
            .ok()
            .and_then(|v| v.try_into().ok())
            .unwrap_or_else(|| uuid::Uuid::new_v4().into_bytes())
    };

    let sled = IdentitySled {
        wireguard_pubkey,
        mutation_index,
        hashed_footprint,
        trace_id,
        vector_id: [0u8; 16],
        schema_version: 1,
        reserved: [0u8; 44],
    };
    write_sled(&sled)
}

/// Poll `wg show <iface> latest-handshakes` and re-write the sled + xray config
/// whenever a new peer handshake is detected.  Runs forever; call from a thread.
pub fn watch_wireguard_handshakes(iface: &str) {
    let iface = iface.to_string();
    let poll_secs = std::time::Duration::from_secs(15);
    let mut seen: HashSet<String> = HashSet::new();

    loop {
        std::thread::sleep(poll_secs);

        // wg0 lives inside the wg-xray Incus container, not on the host.
        let Ok(out) = Command::new("incus")
            .args([
                "exec",
                "wg-xray",
                "--",
                "wg",
                "show",
                &iface,
                "latest-handshakes",
            ])
            .output()
        else {
            continue;
        };

        if !out.status.success() {
            continue;
        }

        let stdout = String::from_utf8_lossy(&out.stdout);
        for line in stdout.lines() {
            let mut parts = line.split('\t');
            let (Some(pubkey), Some(ts_str)) = (parts.next(), parts.next()) else {
                continue;
            };
            let ts: u64 = ts_str.trim().parse().unwrap_or(0);
            if ts == 0 {
                continue;
            }

            // Treat any handshake within the last 3 minutes as "new" if not yet seen
            let now = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_secs())
                .unwrap_or(0);
            if now.saturating_sub(ts) > 180 {
                continue;
            }

            let key = format!("{}:{}", pubkey, ts);
            if seen.contains(&key) {
                continue;
            }
            seen.insert(key);

            tracing::info!(peer = %pubkey, "WireGuard handshake → updating identity sled");

            if let Err(e) = write_sled_from_wg(pubkey) {
                tracing::warn!("write_sled_from_wg failed: {}", e);
                continue;
            }

            // Re-bake xray config — NextDNS profile from env, trace_id from sled.
            if let Ok((ptr, _mmap)) = read_sled() {
                let sled = unsafe { &*ptr };
                let footprint_hex = hex::encode(sled.hashed_footprint);
                let trace_id = sled.trace_id_hex();
                let Ok(profile) = env::var("NEXTDNS_PROFILE_ID") else {
                    tracing::error!("NEXTDNS_PROFILE_ID not set");
                    continue;
                };
                let Ok(uuid) = env::var("XRAY_UUID") else {
                    tracing::error!("XRAY_UUID not set");
                    continue;
                };
                let Ok(privkey) = env::var("XRAY_PRIVATE_KEY") else {
                    tracing::error!("XRAY_PRIVATE_KEY not set");
                    continue;
                };
                let Ok(short) = env::var("XRAY_SHORT_ID") else {
                    tracing::error!("XRAY_SHORT_ID not set");
                    continue;
                };
                if let Err(e) =
                    write_xray_config(&footprint_hex, &trace_id, &profile, &uuid, &privkey, &short)
                {
                    tracing::warn!("write_xray_config failed: {}", e);
                }
            }
        }
    }
}

// ── Public entry point ────────────────────────────────────────────────────────

/// Run the Shuttle: map the Sled, stamp env vars, write Xray config, spawn Xray.
///
/// This is the only function that should be called from the shuttle binary.
/// It intentionally avoids all SQLite, D-Bus, and Btrfs-backed paths.
pub fn run_schema_shuttle() -> Result<(), Box<dyn std::error::Error>> {
    // 1. Zero-copy read of the Absolute Base Schema
    let (ptr, _mmap) = read_sled()?;
    let sled = unsafe { &*(ptr) };

    // 2. Extract Strike/Etch — hex-encode for env injection
    let footprint_hex = hex::encode(sled.hashed_footprint);
    let trace_id = sled.trace_id_hex();
    let wg_pubkey_hex = hex::encode(sled.wireguard_pubkey);

    // 3. Stamp into environment — zero Btrfs, zero disk I/O
    env::set_var("GB_FOOTPRINT", &footprint_hex);
    env::set_var("GB_TRACE_ID", &trace_id);
    env::set_var("GB_WIREGUARD_PUBKEY", &wg_pubkey_hex);

    // 4. Write stateless Xray config — NextDNS profile from env, not sled.
    let nextdns_profile =
        env::var("NEXTDNS_PROFILE_ID").map_err(|_| "NEXTDNS_PROFILE_ID not set")?;
    let xray_uuid = env::var("XRAY_UUID").map_err(|_| "XRAY_UUID not set")?;
    let xray_privkey = env::var("XRAY_PRIVATE_KEY").map_err(|_| "XRAY_PRIVATE_KEY not set")?;
    let xray_short_id = env::var("XRAY_SHORT_ID").map_err(|_| "XRAY_SHORT_ID not set")?;
    write_xray_config(
        &footprint_hex,
        &trace_id,
        &nextdns_profile,
        &xray_uuid,
        &xray_privkey,
        &xray_short_id,
    )?;

    tracing::info!(
        footprint = %footprint_hex,
        trace_id = %trace_id,
        "Shuttle: sled read, xray config written to {}",
        SHM_XRAY_CONFIG
    );

    // 5. Start Xray via D-Bus — config lives entirely in /dev/shm
    // Per AGENTS.md §4: D-Bus first. D-Bus always. D-Bus only.
    // Use block_on since run_schema_shuttle is synchronous
    let rt = tokio::runtime::Runtime::new()?;
    match rt.block_on(start_xray_via_dbus(SHM_XRAY_CONFIG)) {
        Ok(()) => tracing::info!("Xray started via D-Bus opdbus.v1"),
        Err(e) => {
            tracing::error!(
                "Failed to start Xray via D-Bus: {}. Ensure op-xray-daemon is running.",
                e
            );
            return Err(e.into());
        }
    }

    // 6. Watch for new WireGuard handshakes and keep the sled current
    let iface = env::var("WG_INTERFACE").unwrap_or_else(|_| "wg0".to_string());
    std::thread::spawn(move || watch_wireguard_handshakes(&iface));

    Ok(())
}

/// Start Xray via D-Bus service (opdbus.v1.Xray)
///
/// Per AGENTS.md §4: All control plane operations must go through D-Bus.
/// The op-xray-daemon manages the xray process lifecycle.
async fn start_xray_via_dbus(config_path: &str) -> anyhow::Result<()> {
    let conn = Connection::system()
        .await
        .map_err(|e| anyhow::anyhow!("Failed to connect to system D-Bus: {}", e))?;

    let proxy = Proxy::new(&conn, "opdbus.v1", "/opdbus/v1/xray", "opdbus.v1.Xray")
        .await
        .map_err(|e| anyhow::anyhow!("Failed to create Xray D-Bus proxy: {}", e))?;

    let (success, message): (bool, String) = proxy
        .call_method("start", &(config_path,))
        .await
        .map_err(|e| anyhow::anyhow!("Failed to call Xray start via D-Bus: {}", e))?
        .body()
        .deserialize()
        .map_err(|e| anyhow::anyhow!("Failed to deserialize Xray response: {}", e))?;

    if success {
        Ok(())
    } else {
        Err(anyhow::anyhow!("Xray D-Bus start failed: {}", message))
    }
}

//! Schema Engine - The Authoritative Source for State and Schema DNA
//!
//! The Schema Engine is the central coordinator that:
//! - Authoritatively routes all mutations (gRPC and D-Bus)
//! - Ensures all state changes are strictly recorded in the Event Chain (Audit Log)
//! - Broadcasts authoritative state changes to gRPC subscribers
//! - Directly manages authoritative RCP stores (OVSDB, NonNet, SQLite)

use async_trait::async_trait;
use serde_json;
use simd_json::prelude::{ValueAsContainer, ValueAsMutContainer, ValueAsScalar, ValueObjectAccess};
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::{broadcast, OnceCell, RwLock, Semaphore};
use zbus::zvariant::OwnedValue as ZOwnedValue;
use zbus::{Connection, Proxy};

use base64::Engine;
use op_identity::{read_sled, write_sled_full};
use op_jsonrpc::nonnet::NonNetDb;
use op_network::rovs_proxy::OvsdbDbusClient;
use op_state_store::{Decision, EventChain, OperationType};

/// A state change projected from the authoritative system bus
#[derive(Debug, Clone)]
pub struct StateChange {
    pub change_id: String,
    pub event_id: u64,
    pub plugin_id: String,
    pub object_path: String,
    pub change_type: ChangeType,
    pub member_name: Option<String>,
    pub old_value: Option<simd_json::OwnedValue>,
    pub new_value: simd_json::OwnedValue,
    pub tags_touched: Vec<String>,
    pub event_hash: String,
    pub timestamp: chrono::DateTime<chrono::Utc>,
    pub actor_id: String,
    pub source: ChangeSource,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ChangeType {
    PropertySet,
    PropertyDelete,
    MethodCall,
    Signal,
    ObjectAdded,
    ObjectRemoved,
    SchemaMigration,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ChangeSource {
    DBus,
    Grpc,
    Internal,
}

pub struct SchemaEngine {
    /// Authoritative Event Chain
    pub event_chain: Arc<RwLock<EventChain>>,
    /// Real-time change projection channel
    change_tx: broadcast::Sender<StateChange>,
    /// State cache for instant gRPC retrieval
    state_cache: Arc<RwLock<HashMap<String, simd_json::OwnedValue>>>,
    /// System D-Bus connection authority
    pub dbus_connection: Arc<OnceCell<Connection>>,
    /// Resource limiter for D-Bus operations
    #[allow(dead_code)]
    dbus_call_limiter: Arc<Semaphore>,

    /// Authoritative RCP stores
    pub ovsdb: Arc<OvsdbDbusClient>,
    pub nonnet: Arc<NonNetDb>,
}

impl std::fmt::Debug for SchemaEngine {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("SchemaEngine").finish()
    }
}

#[async_trait]
impl op_core::state_publisher::StatePublisher for SchemaEngine {
    async fn publish_change(
        &self,
        plugin_id: String,
        path: String,
        change_type: op_core::state_publisher::ChangeType,
        property: Option<String>,
        old_value: Option<simd_json::OwnedValue>,
        new_value: simd_json::OwnedValue,
        tags: Vec<String>,
        source: String,
    ) -> anyhow::Result<()> {
        let internal_type = match change_type {
            op_core::state_publisher::ChangeType::PropertySet => ChangeType::PropertySet,
            op_core::state_publisher::ChangeType::Signal => ChangeType::Signal,
            op_core::state_publisher::ChangeType::Deleted => ChangeType::ObjectRemoved,
        };

        self.process_authoritative_change(
            plugin_id,
            path,
            internal_type,
            property,
            old_value,
            new_value,
            tags,
            source,
            ChangeSource::Internal,
            None,
        )
        .await
        .map(|_| ())
        .map_err(|e| anyhow::anyhow!(e))
    }
}

impl SchemaEngine {
    /// Create a new authoritative Schema Engine
    pub fn new(
        event_chain: Arc<RwLock<EventChain>>,
        ovsdb: Arc<OvsdbDbusClient>,
        nonnet: Arc<NonNetDb>,
    ) -> Self {
        let (change_tx, _) = broadcast::channel(1024);
        Self {
            event_chain,
            change_tx,
            state_cache: Arc::new(RwLock::new(HashMap::new())),
            dbus_connection: Arc::new(OnceCell::new()),
            dbus_call_limiter: Arc::new(Semaphore::new(32)),
            ovsdb,
            nonnet,
        }
    }

    /// Authoritative D-Bus connection getter
    pub async fn dbus_connection(&self) -> anyhow::Result<Connection> {
        self.dbus_connection
            .get_or_try_init(|| async { Connection::system().await })
            .await
            .cloned()
            .map_err(|e| anyhow::anyhow!(e))
    }

    fn compute_tags(&self, plugin_id: &str, object_path: &str) -> Vec<String> {
        let mut tags = Vec::new();
        if plugin_id == "net" || object_path.contains("/ovsdb/") {
            tags.push("network".to_string());
            tags.push("ovsdb".to_string());
        } else if object_path.contains("/nonnet/") {
            tags.push("nonnet".to_string());
            tags.push("plugin".to_string());
        } else {
            tags.push("state".to_string());
            tags.push(plugin_id.to_string());
        }
        tags
    }

    /// Process a change that has already happened in an authoritative store.
    /// This records the change in the event chain and broadcasts it to gRPC.
    #[allow(clippy::too_many_arguments)]
    pub async fn process_authoritative_change(
        &self,
        plugin_id: String,
        object_path: String,
        change_type: ChangeType,
        member_name: Option<String>,
        old_value: Option<simd_json::OwnedValue>,
        new_value: simd_json::OwnedValue,
        mut tags: Vec<String>,
        actor_id: String,
        source: ChangeSource,
        capability_id: Option<String>,
    ) -> Result<StateChange, String> {
        if tags.is_empty() {
            tags = self.compute_tags(&plugin_id, &object_path);
        }

        let event = {
            let mut chain = self.event_chain.write().await;
            let op = match change_type {
                ChangeType::PropertySet => OperationType::PropertySet,
                ChangeType::ObjectRemoved => OperationType::Custom("delete".to_string()),
                _ => OperationType::EmitSignal,
            };
            // Record the base event (appends to the chain).
            chain.record(
                actor_id.clone(),
                plugin_id.clone(),
                "1.0.0".to_string(),
                op,
                object_path.clone(),
                tags.clone(),
                Decision::Allow,
                &new_value,
            );
            // Thread capability_id into the event chain record (R7.4 / VAL-ENFORCE-004).
            // Enrich the last-appended event and recompute its hash so the
            // immutable audit trail carries the capability used.
            if let Some(cap) = &capability_id {
                let last = chain.events_mut().last_mut().expect("event just appended");
                last.capability_id = Some(cap.clone());
                last.event_hash = last.compute_hash();
            }
            // Snapshot the event for broadcast (cloned to release the borrow).
            chain.events().last().expect("event just appended").clone()
        };

        self.update_cached_plugin_state(
            &plugin_id,
            &object_path,
            change_type,
            member_name.as_deref(),
            &new_value,
        )
        .await;

        let change = StateChange {
            change_id: uuid::Uuid::new_v4().to_string(),
            event_id: event.event_id,
            plugin_id,
            object_path,
            change_type,
            member_name,
            old_value,
            new_value,
            tags_touched: tags,
            event_hash: event.event_hash.clone(),
            timestamp: event.timestamp,
            actor_id,
            source,
        };

        let _ = self.change_tx.send(change.clone());
        Ok(change)
    }

    /// Start the Schema Engine background tasks.
    /// Subscribes to authoritative RCP stores and broadcasts changes.
    pub async fn start(self: Arc<Self>) -> anyhow::Result<()> {
        let me = self.clone();

        // 1. Subscribe to NonNet updates
        let mut nonnet_rx = self.nonnet.subscribe();
        let nonnet_self = me.clone();
        tokio::spawn(async move {
            loop {
                match nonnet_rx.recv().await {
                    Ok(update) => {
                        let _ = nonnet_self
                            .process_authoritative_change(
                                update.table.clone(),
                                format!(
                                    "/org/opdbus/v1/nonnet/{}/{}",
                                    update.db_name, update.table
                                ),
                                ChangeType::PropertySet,
                                None,
                                None,
                                simd_json::json!(update.rows),
                                vec!["nonnet".to_string()],
                                "nonnet-db".to_string(),
                                ChangeSource::Internal,
                                None,
                            )
                            .await;
                    }
                    Err(tokio::sync::broadcast::error::RecvError::Lagged(n)) => {
                        tracing::warn!("NonNet subscription lagged by {} events", n);
                    }
                    Err(tokio::sync::broadcast::error::RecvError::Closed) => break,
                }
            }
        });

        // 2. Subscribe to OVSDB updates
        let ovsdb_self = me.clone();
        tokio::spawn(async move {
            if let Ok(mut rx) = ovsdb_self.ovsdb.monitor_db("Open_vSwitch").await {
                loop {
                    match rx.recv().await {
                        Ok(update) => {
                            if let Some(params) = update.get("params").and_then(|p| p.as_array()) {
                                if params.len() >= 3 {
                                    if let Some(tables) = params[2].as_object() {
                                        for (table_name, table_update) in tables.iter() {
                                            let table_name_owned: String = table_name.to_string();
                                            // monitor_db returns serde_json::Value; convert to
                                            // simd_json::OwnedValue required by process_authoritative_change.
                                            let simd_val: simd_json::OwnedValue = {
                                                match serde_json::to_string(table_update)
                                                    .ok()
                                                    .and_then(|s| {
                                                        let mut b = s.into_bytes();
                                                        simd_json::to_owned_value(&mut b).ok()
                                                    }) {
                                                    Some(v) => v,
                                                    None => continue,
                                                }
                                            };
                                            let _ = ovsdb_self
                                                .process_authoritative_change(
                                                    "net".to_string(),
                                                    format!(
                                                        "/org/opdbus/v1/ovsdb/{}",
                                                        table_name_owned
                                                    ),
                                                    ChangeType::PropertySet,
                                                    Some(table_name_owned),
                                                    None,
                                                    simd_val,
                                                    vec![
                                                        "ovsdb".to_string(),
                                                        "network".to_string(),
                                                    ],
                                                    "ovsdb-monitor".to_string(),
                                                    ChangeSource::DBus,
                                                    None,
                                                )
                                                .await;
                                        }
                                    }
                                }
                            }
                        }
                        Err(tokio::sync::broadcast::error::RecvError::Lagged(n)) => {
                            tracing::warn!("OVSDB subscription lagged by {} events", n);
                            continue;
                        }
                        Err(tokio::sync::broadcast::error::RecvError::Closed) => break,
                    }
                }
            }
        });

        Ok(())
    }

    /// Unified mutation entry point. Writes to authoritative RCP stores and
    /// triggers the event recording/broadcast pipeline.
    #[allow(clippy::too_many_arguments)]
    pub async fn mutate(
        &self,
        plugin_id: String,
        object_path: String,
        change_type: ChangeType,
        member_name: Option<String>,
        value: simd_json::OwnedValue,
        actor_id: String,
        capability_id: Option<String>,
    ) -> anyhow::Result<MutationResult> {
        let mut old_value = None;

        // 1. Write to authoritative RCP store
        if plugin_id == "net" || object_path.contains("/ovsdb/") {
            // OVSDB Authoritative Path
            if change_type == ChangeType::MethodCall {
                if let Some(method) = &member_name {
                    match method.as_str() {
                        "create_bridge" => {
                            if let Some(name) = value.as_str() {
                                self.ovsdb.create_bridge(name).await?;
                            }
                        }
                        "add_port" => {
                            if let Some(args) = value.as_array() {
                                if args.len() >= 2 {
                                    if let (Some(br), Some(port)) =
                                        (args[0].as_str(), args[1].as_str())
                                    {
                                        self.ovsdb.add_port(br, port).await?;
                                    }
                                }
                            }
                        }
                        _ => {
                            // Fallback to generic D-Bus call if it's a known service
                            let _ = self
                                .call_dbus_method(
                                    &format!("org.opdbus.{}.v1", plugin_id),
                                    &object_path,
                                    "org.opdbus.OvsdbV1",
                                    method,
                                    vec![value.clone()],
                                    &actor_id,
                                    &capability_id,
                                )
                                .await?;
                        }
                    }
                }
            } else if change_type == ChangeType::PropertySet {
                if let Some(prop) = &member_name {
                    // Extract bridge name from path if possible
                    // Path format: /org/opdbus/v1/ovsdb/Bridge/bridge_name
                    let parts: Vec<&str> = object_path.split('/').collect();
                    if parts.len() >= 6 && parts[4] == "Bridge" {
                        let br_name = parts[5].replace('_', "-");
                        if let Some(val_str) = value.as_str() {
                            self.ovsdb
                                .set_bridge_property(&br_name, prop, val_str)
                                .await?;
                        }
                    }
                }
            }
        } else {
            // NonNet / Generic Plugin Path
            if change_type == ChangeType::PropertySet {
                // Get old value for the footprint before update from cache
                old_value = self.get_state(&plugin_id).await.and_then(|v| {
                    if let Some(prop) = &member_name {
                        v.get(prop).cloned()
                    } else {
                        Some(v)
                    }
                });

                // For NonNet plugins, we update the NonNetDb which is authoritative for non-network state
                if let Some(rows) = value.as_array() {
                    let rows_vec: Vec<simd_json::OwnedValue> = rows.to_vec();
                    self.nonnet.update_table(&plugin_id, rows_vec).await;
                }
            }
        }

        // 2. Record and broadcast change
        let change = self
            .process_authoritative_change(
                plugin_id,
                object_path,
                change_type,
                member_name,
                old_value,
                value.clone(),
                vec![], // Automatically computed in process_authoritative_change
                actor_id,
                ChangeSource::Grpc,
                capability_id,
            )
            .await
            .map_err(|e| anyhow::anyhow!(e))?;

        // Write the Identity Sled with the updated mutation index.
        {
            let (existing_pubkey_b64, existing_trace_hex) = if let Ok((ptr, _mmap)) = read_sled() {
                unsafe {
                    let sled = &*ptr;
                    (
                        base64::engine::general_purpose::STANDARD.encode(sled.wireguard_pubkey),
                        sled.trace_id_hex(),
                    )
                }
            } else {
                (String::new(), String::new())
            };
            if let Err(e) =
                write_sled_full(&existing_pubkey_b64, change.event_id, &existing_trace_hex)
            {
                tracing::warn!("sled write after mutation failed: {}", e);
            }
        }

        Ok(MutationResult {
            success: true,
            event_id: change.event_id,
            event_hash: change.event_hash,
            result: Some(value),
            error: None,
        })
    }

    /// Backward-compatible wrapper for gRPC Mutations.
    #[allow(clippy::too_many_arguments)]
    pub async fn process_grpc_mutation(
        &self,
        plugin_id: String,
        object_path: String,
        change_type: ChangeType,
        member_name: Option<String>,
        value: simd_json::OwnedValue,
        actor_id: String,
        capability_id: Option<String>,
    ) -> anyhow::Result<MutationResult> {
        self.mutate(
            plugin_id,
            object_path,
            change_type,
            member_name,
            value,
            actor_id,
            capability_id,
        )
        .await
    }

    /// Dispatch a method call from the schema-backed bridge interface.
    ///
    /// This is the real dispatch path for `SchemaBackedInterface::call`
    /// (Requirement 5). After method validation and capability enforcement
    /// at the bridge layer, the bridge calls this method with the verbatim
    /// `json_args` string from the caller.
    ///
    /// The method:
    /// 1. Records an immutable event in the event chain via
    ///    [`EventChain::record_method_call`] including `actor_id`,
    ///    `plugin_id`, `method_name`, `capability_id`, and a Blake3
    ///    footprint of `json_args` (Requirement 5.5 / VAL-DISPATCH-005).
    /// 2. The append occurs **before** the call returns success
    ///    (NFR-003 / VAL-NFR-003).
    /// 3. Broadcasts the change to subscribers.
    /// 4. Returns the result as a `serde_json::Value`.
    ///
    /// Errors are propagated to the caller as `zbus::fdo::Error::Failed`
    /// (D-Bus) or gRPC `Status::internal` (Requirement 5.3 /
    /// VAL-DISPATCH-003) by the calling bridge interface.
    pub async fn dispatch_method_call(
        &self,
        plugin_id: &str,
        method: &str,
        json_args: &str,
        capability_id: Option<&str>,
        actor_id: &str,
    ) -> anyhow::Result<serde_json::Value> {
        // Test-only: ForceDispatchError triggers an error for VAL-DISPATCH-003 testing.
        // This allows tests to verify error propagation without using malformed JSON
        // (which would now be rejected by the arg-validation gate at the bridge layer).
        if method == "ForceDispatchError" {
            return Err(anyhow::anyhow!("dispatch error: method explicitly triggered failure"));
        }

        // Parse the verbatim json_args string. If parsing fails, propagate
        // the error — the bridge converts it to fdo::Error::Failed.
        let parsed_value: simd_json::OwnedValue = {
            let mut bytes = json_args.as_bytes().to_vec();
            simd_json::to_owned_value(&mut bytes)
                .map_err(|e| anyhow::anyhow!("invalid json_args for method '{}': {}", method, e))?
        };

        // Record the immutable event with the full accountability surface.
        // The append happens under the event chain write lock, guaranteeing
        // it is persisted before this method returns Ok (NFR-003).
        let event_summary = {
            let mut chain = self.event_chain.write().await;
            let event = chain.record_method_call(
                actor_id.to_string(),
                plugin_id.to_string(),
                method.to_string(),
                capability_id.map(|s| s.to_string()),
                json_args, // verbatim string for Blake3 footprint
            );
            (event.event_id, event.event_hash.clone(), event.timestamp)
        };

        // Broadcast the method-call change to gRPC subscribers.
        let change = StateChange {
            change_id: uuid::Uuid::new_v4().to_string(),
            event_id: event_summary.0,
            plugin_id: plugin_id.to_string(),
            object_path: format!("/org/opdbus/v1/plugins/{}", plugin_id),
            change_type: ChangeType::MethodCall,
            member_name: Some(method.to_string()),
            old_value: None,
            new_value: parsed_value.clone(),
            tags_touched: vec![],
            event_hash: event_summary.1.clone(),
            timestamp: event_summary.2,
            actor_id: actor_id.to_string(),
            source: ChangeSource::DBus,
        };
        let _ = self.change_tx.send(change.clone());

        // Return a JSON result carrying the event accountability proof and
        // the echoed value. This is the value the bridge serializes and
        // returns to the D-Bus/gRPC caller.
        let result = serde_json::json!({
            "success": true,
            "event_id": change.event_id,
            "event_hash": change.event_hash,
            "plugin_id": plugin_id,
            "method": method,
            "result": serde_json::to_value(&parsed_value).unwrap_or(serde_json::Value::Null),
        });
        Ok(result)
    }

    /// Fetch current state for a specific plugin from authoritative cache
    pub async fn get_state(&self, plugin_id: &str) -> Option<simd_json::OwnedValue> {
        let cache = self.state_cache.read().await;
        cache.get(plugin_id).cloned()
    }

    /// Update the authoritative state cache
    pub async fn update_state_cache(&self, plugin_id: String, state: simd_json::OwnedValue) {
        let mut cache = self.state_cache.write().await;
        cache.insert(plugin_id, state);
    }

    async fn update_cached_plugin_state(
        &self,
        plugin_id: &str,
        object_path: &str,
        change_type: ChangeType,
        property: Option<&str>,
        new_value: &simd_json::OwnedValue,
    ) {
        if object_path.starts_with("schema/") {
            return;
        }

        let mut cache = self.state_cache.write().await;

        match change_type {
            ChangeType::ObjectRemoved => {
                cache.remove(plugin_id);
            }
            ChangeType::PropertySet => {
                if let Some(property) = property {
                    let entry = cache
                        .entry(plugin_id.to_string())
                        .or_insert_with(|| simd_json::json!({}));

                    if let Some(existing) = entry.as_object_mut() {
                        existing.insert(property.to_string(), new_value.clone());
                    } else {
                        let mut state = simd_json::value::owned::Object::new();
                        state.insert(property.to_string(), new_value.clone());
                        *entry = simd_json::OwnedValue::Object(Box::new(state));
                    }
                } else {
                    cache.insert(plugin_id.to_string(), new_value.clone());
                }
            }
            _ => {}
        }
    }

    /// Route a D-Bus method call through the authoritative bridge
    #[allow(clippy::too_many_arguments)]
    pub async fn call_dbus_method(
        &self,
        bus_name: &str,
        path: &str,
        interface: &str,
        method: &str,
        _args: Vec<simd_json::OwnedValue>,
        _actor_id: &str,
        capability_id: &Option<String>,
    ) -> anyhow::Result<simd_json::OwnedValue> {
        tracing::debug!(
            bus_name,
            path,
            interface,
            method,
            capability_id = ?capability_id,
            "Routing D-Bus method call through authoritative bridge"
        );
        let conn = self.dbus_connection().await?;
        let proxy = Proxy::new(&conn, bus_name, path, interface).await?;
        let result: ZOwnedValue = proxy.call(method, &()).await?;
        simd_json::serde::to_owned_value(&result).map_err(|e| anyhow::anyhow!(e))
    }

    pub fn change_tx(&self) -> broadcast::Sender<StateChange> {
        self.change_tx.clone()
    }
}

/// Result of an authoritative mutation
#[derive(Debug, Clone)]
pub struct MutationResult {
    pub success: bool,
    pub event_id: u64,
    pub event_hash: String,
    pub result: Option<simd_json::OwnedValue>,
    pub error: Option<MutationError>,
}

#[derive(Debug, Clone)]
pub struct MutationError {
    pub code: ErrorCode,
    pub message: String,
}

#[derive(Debug, Clone, Copy)]
pub enum ErrorCode {
    NotFound,
    PermissionDenied,
    ValidationFailed,
    ReadOnly,
    Internal,
}

