async fn call_method(
        &self,
        request: Request<CallMethodRequest>,
    ) -> Result<Response<CallMethodResponse>, Status> {
        // Inbound connection arrival: compare the producer's catalog_hash and
        // reload the SHM catalog before dispatch if it changed (no polling).
        self.refresh_schema_on_inbound().await;

        // Extract capability context from interceptor (VAL-ENFORCE-001).
        // The GhostbridgeInterceptor has already validated the footprint and
        // loaded grants. We use this context for capability enforcement.
        let ctx: Option<interceptor::GhostbridgeContext> = request.extensions().get();

        let req = request.into_inner();
        let args: Vec<simd_json::OwnedValue> = req
            .arguments
            .into_iter()
            .map(|v| prost_value_to_simd(&v))
            .collect();

        // Load the method schema to check required_capability (VAL-ENFORCE-002).
        // Read from the router's cached routes (SHM-loaded).
        if let Some(router) = &self.schema_router {
            if let Some(Some(route)) = router.get_route(&req.plugin_id).await.as_ref().some() {
                if let Some(method_decl) = route.methods.get(&req.method_name) {
                    if let Some(required_cap) = method_decl
                        .get("required_capability")
                        .and_then(|c| c.as_str())
                        .filter(|s| !s.is_empty())
                    {
                        // VAL-ENFORCE-002: Check if the caller's footprint grants the capability.
                        // VAL-ENFORCE-003: If not granted, deny without calling mutate.
                        let grants = match &ctx {
                            Some(c) => &c.granted_capabilities,
                            None => &std::collections::HashSet::new(),
                        };
                        if !grants.contains(required_cap) {
                            return Err(Status::permission_denied(format!(
                                "capability '{}' required for method '{}' is not granted",
                                required_cap, req.method_name
                            )));
                        }
                    }
                }
            }
        }

        // New pipeline: Route through SchemaEngine.mutate for authoritative recording.
        let result = self
            .schema_engine
            .mutate(
                req.plugin_id.clone(),
                req.object_path.clone(),
                ChangeType::MethodCall,
                Some(req.method_name.clone()),
                simd_json::json!(args),
                req.actor_id.clone(),
                if req.capability_id.is_empty() {
                    None
                } else {
                    Some(req.capability_id.clone())
                },
            )
            .await;

        match result {
            Ok(ok) => Ok(Response::new(CallMethodResponse {
                success: ok.success,
                result: ok.result.map(|v| simd_to_prost_value(&v)),
                event_id: ok.event_id,
                event_hash: ok.event_hash,
                error: None,
            })),
            Err(e) => Ok(Response::new(CallMethodResponse {
                success: false,
                result: None,
                event_id: 0,
                event_hash: String::new(),
                error: Some(ProtoMutationError {
                    code: ProtoErrorCode::Internal as i32,
                    message: e.to_string(),
                    deny_reason: None,
                }),
            })),
        }
    }

