            reserved: [0u8; 44],
            vector_id: [0xCC; 16],
        };
        op_identity::write_sled(&sled).unwrap();
        std::env::set_var("OP_SLED_PATH", base.join("plugin_schema.dat").into_os_string());

        // No grants - capability check should fail before mutate
        let grants_path = base.join("opdbus/capability-grants.json");
        std::fs::create_dir_all(grants_path.parent().unwrap()).unwrap();
        std::fs::write(&grants_path, serde_json::to_vec(&json!({})).unwrap()).unwrap();

        let engine = test_engine();
        let route = dispatch_test_route();
        let iface =
            SchemaBackedInterface::with_engine("beta".to_string(), route, Some(engine.clone()));

        // Test 1: Unknown method → UnknownMethod without mutate
        let result = iface.call("NonexistentMethod".to_string(), "{}".to_string()).await;
        assert!(matches!(result, Err(zbus::fdo::Error::UnknownMethod(_))));
        let chain = engine.event_chain.read().await;
        assert!(chain.events().is_empty(), "unknown method: no mutate");

        // Test 2: Invalid args → InvalidArgs without mutate
        let result = iface.call("SetKey".to_string(), "{}".to_string()).await;
        assert!(matches!(result, Err(zbus::fdo::Error::InvalidArgs(_))));
        let chain = engine.event_chain.read().await;
        assert!(chain.events().is_empty(), "invalid args: no mutate");

        // Test 3: Missing capability → AccessDenied without mutate
        let result = iface
            .call("SetKey".to_string(), r#"{"key":"test"}"#.to_string())
            .await;
        assert!(matches!(result, Err(zbus::fdo::Error::AccessDenied(_))));
        let chain = engine.event_chain.read().await;
        assert!(chain.events().is_empty(), "missing capability: no mutate");

        // Test 4: Null required_capability → mutate succeeds
        let result = iface.call("GetKey".to_string(), "{}".to_string()).await;
        assert!(result.is_ok(), "null required_capability should succeed");
        let chain = engine.event_chain.read().await;
        assert_eq!(chain.events().len(), 1, "null required_capability: mutate called");

        cleanup(&base);
        std::env::remove_var("OP_SLED_PATH");
    }
}


