    fn test_base_dir() -> std::path::PathBuf {
        let id = std::process::id();
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let dir = std::path::PathBuf::from(format!("/dev/shm/opdbus-test-interceptor-{}-{}", id, nanos));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).expect("create test base dir");
        dir
    }

    fn sled_path(base: &std::path::PathBuf) -> String {
        base.join("plugin_schema.dat").to_string_lossy().into_owned()
    }

    fn write_test_sled(base: &std::path::PathBuf) -> (String, String) {
        let sled = IdentitySled {
            wireguard_pubkey: [0xAA; 32],
            mutation_index: 1,
            hashed_footprint: [0xBB; 32],
            trace_id: [0xCC; 16],
            schema_version: 1,
            reserved: [0u8; 44],
            vector_id: [0xDD; 16],
        };
        let footprint_hex = hex::encode(sled.hashed_footprint);
        let trace_hex = hex::encode(sled.trace_id);

        // Write sled bytes directly to the custom path (bypass write_sled's hardcoded path)
        let sled_path = sled_path(base);
        let bytes: &[u8] = unsafe {
            std::slice::from_raw_parts(&sled as *const IdentitySled as *const u8, IdentitySled::SIZE)
        };
        let tmp = format!("{}.tmp", sled_path);
        let mut f = std::fs::File::create(&tmp).unwrap();
        std::io::Write::write_all(&mut f, bytes).unwrap();
        f.sync_data().unwrap();
        std::fs::rename(&tmp, &sled_path).unwrap();

        // Also set up grants path at the expected SHM location
        std::env::set_var("OP_SLED_PATH", sled_path);

        (footprint_hex, trace_hex)
    }

    fn cleanup(path: &std::path::Path) {
        let _ = std::fs::remove_dir_all(path);
    }
